/**
 *  1. sys_config 配置表中新增 unsaved_change 未保存提示开关
 *  2. sys_menu 数据更新，删除关联 角色脏数据
 */
DELETE from `sys_config` where param_key = "unsaved_change";

delete from sys_role_menu where menu_id in (
select id from sys_menu where name in ('panel_save','panel_chart_save','explore_chart_save','asset_save','asset_endpoint_save','asset_chart_save','asset_vendor_save','project_save','project_topo_edit','project_module_save','project_endpoint_save','project_endpoint_query_chart_save','rule_save','account_save','role_save','prom_save','dc_save','dc_cabinet_save','model_save','model_chart_save','snmp_file_save')
);

truncate sys_menu;

